// Groupe les tickets NOUVEAU en dépassement SLA PAR AGENCE.
// On utilise /api/tickets (qui porte agenceName) car /api/tickets/queue?agenceId
// n'est pas filtré côté backend. Une sortie par agence concernée.
const data = $input.first().json;
const tickets = data.content || [];
const now = Date.now();
const SLA_MIN = 120;
const MAX_LINES = 10; // évite un message WhatsApp géant

const byAgence = {};
for (const t of tickets) {
  if (t.statut !== 'NOUVEAU' || !t.agenceName || !t.createdAt) continue;
  const mins = (now - new Date(t.createdAt).getTime()) / 60000;
  if (mins <= SLA_MIN) continue;
  if (!byAgence[t.agenceName]) byAgence[t.agenceName] = [];
  byAgence[t.agenceName].push({ num: t.numero || 'N/A', client: t.clientNom || 'client', canal: t.canal || '?', mins: Math.round(mins) });
}

const out = [];
for (const agence of Object.keys(byAgence)) {
  const list = byAgence[agence].sort((a, b) => b.mins - a.mins);
  const shown = list.slice(0, MAX_LINES);
  const lines = shown.map(t => `• ${t.num} — ${t.client} (${t.canal}) — ${t.mins} min`).join('\n');
  const extra = list.length > MAX_LINES ? `\n…et ${list.length - MAX_LINES} autre(s).` : '';
  const message = `⚠️ *Alerte SLA — ${agence}*\n${list.length} ticket(s) en attente depuis plus de ${SLA_MIN} min :\n\n${lines}${extra}\n\n👉 Merci de les prendre en charge rapidement.`;
  out.push({ json: { agence, message, count: list.length } });
}
return out;
